import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const BIOCHEM_DISCLOSURE = {
  status: 'conceptual_diagram_only' as const,
  summary:
    'Delivered with explicit cellular compartment, substrate–product flux, rate-limiting enzyme, ATP/NADH energetics, regulation, and clinical metabolic tables plus 2D pathway schematics.',
};

function makeBiochemChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  locationAndFlux: string,
  summary: string,
  readingKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'biochemistry',
    chapterCode: `F${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['secondary_premed', 'medical_foundations', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_ncp_bio_9_12', gradeOrYear: 'Grade XI', unitOrModule: `Biological Molecules & Enzymes (${chapterTitle})`, status: 'elective' },
      { frameworkId: 'us_ap_bio', gradeOrYear: 'AP Bio Unit 3', unitOrModule: `Cellular Energetics (${chapterTitle})`, status: 'optional' },
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 1–2', unitOrModule: `Medical Biochemistry (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Metabolic Flux & Enzyme Regulation (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Carbonyl, phosphate ester & peptide bonds', 'Free energy ΔG & ATP hydrolysis'],
    learningObjectives: [
      `Specify the subcellular compartment, starting substrates, end products, and net ATP/NADH/FADH2 stoichiometry of ${chapterTitle.toLowerCase()}.`,
      `Explain allosteric and hormonal (insulin/glucagon/epinephrine) regulation of the committed rate-limiting enzymes.`,
      `Diagnose biochemical blocks and classic metabolic disorders associated with ${chapterTitle.toLowerCase()}.`,
    ],
    depthExplanations: {
      secondary_premed: `${summary} Pathway site & logic: ${locationAndFlux}. Enzymes speed biochemical conversions cleanly at 37 °C without shifting reaction equilibrium.`,
      medical_foundations: `Compartment & flux: ${locationAndFlux}. ${mechanisms.join(' ')} Clinical pathology: ${clinical}`,
      allied_health: `Understanding ${chapterTitle.toLowerCase()} explains blood-glucose trends, ketone/lactate monitoring, vitamin cofactor deficiency risks, and parenteral/enteral nutrition.`,
      graduate_research: `Thermodynamic flux control integrates ΔG′° coupling, covalent AMPK/PKA phosphorylation cascades, substrate cycling amplification, and isotopic mass-spectrometry fluxomics across ${locationAndFlux}.`,
    },
    keyConcepts: [
      { term: 'Location, Substrates & Yield', definition: locationAndFlux },
      { term: 'Rate-Limiting & Regulation', definition: mechanisms[0] ?? summary },
      { term: 'Inherited / Acquired Disorder', definition: clinical },
    ],
    keyFacts: [
      `Subcellular Localization & Energetics: ${locationAndFlux}`,
      'Irreversible (highly exergonic ΔG < 0) committed steps serve as the primary sites of allosteric and covalent hormonal control.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Enzymes supply free energy to make unfavourable reactions spontaneous.', correction: 'Enzymes lower activation energy (Ea) equally for forward and reverse paths; thermodynamic favourability requires coupling to ATP/NADPH hydrolysis or mass action.' },
      { misconception: 'Catabolism and anabolism run simultaneously in reverse along the exact same enzyme path.', correction: 'Reciprocal allosteric/hormonal regulation prevents futile ATP-burning cycles across compartmentalized irreversible bypass enzymes.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} operates inside defined compartments (${locationAndFlux}), linking substrate entry, regulated enzymes, cofactor balance, and clinical biomarker interpretation.`,
    keyTakeaways: [
      locationAndFlux,
      mechanisms[0] ?? summary,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_physiology', relation: 'Hormonal insulin/glucagon shifts steer pathway dominance across liver, muscle, brain, and adipose tissue.' },
      { domainId: 'nutrition_health', relation: 'B-vitamins serve directly as essential enzymatic cofactors (TPP, FAD, NAD+, PLP, biotin, B12).' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', 'structured_text'],
    diagram: {
      id: `diag-f${num}`,
      title: `${chapterTitle} — Pathway Flux & Control Nodes`,
      kind: 'pathway',
      caption: locationAndFlux,
      disclaimer: 'Conceptual metabolic pathway schematic.',
      nodes: [
        { id: 'n1', label: 'Substrate & Compartment', sublabel: locationAndFlux.slice(0, 62), tone: 'blue' },
        { id: 'n2', label: 'Rate-Limiting Enzyme Step', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n3', label: 'Terminal Yield & Clinical Link', sublabel: clinical.slice(0, 62), tone: 'emerald' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Cofactor & allosteric activation' },
        { from: 'n2', to: 'n3', label: 'Net ATP / NADH / metabolic product output' },
      ],
    },
    assetDisclosure: BIOCHEM_DISCLOSURE,
    activity: {
      title: `Metabolic Flux & Enzyme Block Prediction (${chapterTitle})`,
      kind: 'calculation',
      prompt: `Map the subcellular location (${locationAndFlux}), trace ATP/NADH balance, and predict which upstream metabolite accumulates if the rate-limiting enzyme is deficient.`,
      keyTakeaway: clinical,
    },
    readingKeys: [readingKey, 'ap_ch24_nutrition'],
    shortAnswers: [
      { id: `sa-f${num}-1`, prompt: `State the compartment, primary substrates, end products, and rate-limiting enzyme(s) of ${chapterTitle}.`, expectedPoints: [locationAndFlux, mechanisms[0] ?? ''], modelAnswer: `${locationAndFlux}. Control: ${mechanisms.join(' ')}`, level: 'medical_foundations' },
      { id: `sa-f${num}-2`, prompt: `Compare ${comp.colA} versus ${comp.colB} hormonally or mechanistically.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'secondary_premed' },
      { id: `sa-f${num}-3`, prompt: `Explain the biochemical mechanism of a clinical disorder disrupting ${chapterTitle.toLowerCase()}.`, expectedPoints: [clinical], modelAnswer: clinical, level: 'medical_foundations' },
    ],
    appliedCase: {
      id: `app-f${num}-1`,
      title: `Inborn Error & Hormonal Regulation Analysis: ${chapterTitle}`,
      scenario: `A teaching biochemical vignette examines fasting or postprandial metabolite accumulation across ${locationAndFlux}.`,
      questions: ['Which enzymatic step is rate-limiting or blocked?', 'How do upstream metabolites and energy carriers shift?'],
      workedSolution: `Compartment & flux: ${locationAndFlux}. Clinical correlation: ${clinical}`,
      level: 'medical_foundations',
    },
    selfChecks: mcqs,
  };
}

